import json,pathlib,subprocess,sys,tempfile,yaml
ROOT=pathlib.Path.cwd();TOOL='/tmp/opsforge-prometheus-3.5.0/prometheus-3.5.0.linux-amd64/promtool'
if __name__=='__main__':
    unit=json.loads((ROOT/'unit_public.json').read_text());unit['rule_files']=[str(ROOT/'rules.yml')]
    candidate=yaml.safe_load((ROOT/'rules.yml').read_text());alert=next(rule for group in candidate['groups']for rule in group['rules']if rule.get('alert')=='OwnedDiskWillFill')
    for test in unit['tests']:
        for check in test.get('alert_rule_test',[]):
            for expected in check['exp_alerts']:
                expected['exp_labels']={k:v for k,v in expected['exp_labels'].items()if k in('instance','mountpoint','fstype')};expected['exp_labels'].update(alert.get('labels',{}));expected['exp_annotations']=alert.get('annotations',{})
    with tempfile.TemporaryDirectory(prefix='of-predict-public-')as directory:
        path=pathlib.Path(directory)/'unit.yml';path.write_text(json.dumps(unit));result=subprocess.run([TOOL,'test','rules',str(path)],capture_output=True,text=True,timeout=10)
        print('PUBLIC_NATIVE_RULE_ENGINE:'+json.dumps({'exit_code':result.returncode,'stdout':result.stdout,'stderr':result.stderr,'synthetic_input_actual_promtool':True}),flush=True)
    sys.exit(result.returncode)

solution_files.rules.yml:
{
  "groups": [
    {
      "name": "owned_disk_prediction",
      "rules": [
        {
          "record": "opsforge:disk_predicted_avail_bytes:5m",
          "expr": "predict_linear(node_filesystem_avail_bytes{mountpoint=\"/data\"}[5m], 300)"
        },
        {
          "alert": "OwnedDiskWillFill",
          "expr": "(predict_linear(node_filesystem_avail_bytes{mountpoint=\"/data\"}[5m], 300) < 0) and (node_filesystem_avail_bytes{mountpoint=\"/data\"} < 200) and (changes(node_filesystem_size_bytes{mountpoint=\"/data\"}[5m]) == 0) and (deriv(node_filesystem_avail_bytes{mountpoint=\"/data\"}[5m]) < 0) and (abs(deriv(node_filesystem_avail_bytes{mountpoint=\"/data\"}[2m]) - deriv(node_filesystem_avail_bytes{mountpoint=\"/data\"}[5m])) <= abs(deriv(node_filesystem_avail_bytes{mountpoint=\"/data\"}[5m])) * 0.1)",
          "for": "2m",
          "labels": {
            "scope": "private",
            "prediction_window": "5m",
            "horizon": "5m"
          },
          "annotations": {
            "assumption": "linear-window heuristic, not a capacity guarantee"
          }
        }
      ]
    }
  ]
}

